/* @autogenerated */
import { inject, Injectable, Signal } from '@angular/core';
import { distinctUntilChanged, map, merge, skip, switchMap } from 'rxjs';
import { Acl } from '../acl/acl.model';
import { RuntimeConfigService } from '@shared/context/config/app-config.service';
import { AppStateService } from '@shared/context/state/app-state.service';
import { CacheResource } from './cache-resource';
import { Slide } from './provider/repository-provider.interface';

/** Vida por defecto (ms) de la caché si no la fijan `data.cache-ttl` ni los metadatos. */
export const DEFAULT_CACHE_TTL = 3_000;

export type CacheMap<T> = { [key: string]: { cache: CacheResource<T>; observers: number } };

/** Caché de un repositorio: compartida por todas las instancias con el mismo nombre. */
export interface RepositoryCache {
  listMap: { [key: string]: { cache: CacheResource<Slide<any>>; observers: number; query: any } };
  resourceMap: CacheMap<any>;
  resourceAclData: CacheMap<Acl>;
}

/**
 * Cachés de todos los repositorios. Se vacía al cambiar el usuario de cualquier identidad
 * (inicio y cierre de sesión) y al cambiar de tenant, para no mostrar datos de la sesión anterior.
 */
@Injectable({ providedIn: 'root' })
export class RepositoryStore {
  private readonly caches = new Map<string, RepositoryCache>();
  private readonly configuredTtl: Signal<number | undefined>;

  constructor() {
    const config = inject(RuntimeConfigService);
    const state = inject(AppStateService);
    this.configuredTtl = config.value('data.cache-ttl');
    // skip(1): el valor inicial no es un cambio de sesión
    state.tenant$.pipe(distinctUntilChanged(), skip(1)).subscribe(() => this.clear());
    config
      .value$('identity')
      .pipe(
        switchMap((identities) =>
          merge(
            ...Object.keys(identities ?? {}).map((name) =>
              state.user$(name).pipe(
                map((user) => user.uid),
                distinctUntilChanged(),
                skip(1),
              ),
            ),
          ),
        ),
      )
      .subscribe(() => this.clear());
  }

  /** Caché del repositorio `name`; se crea vacía la primera vez. */
  of(name: string): RepositoryCache {
    let cache = this.caches.get(name);
    if (!cache) {
      cache = { listMap: {}, resourceMap: {}, resourceAclData: {} };
      this.caches.set(name, cache);
    }
    return cache;
  }

  /** Vida de la caché: la de los metadatos, la de `data.cache-ttl` o la de por defecto. */
  ttl(own?: number): number {
    return validTtl(own) ?? validTtl(this.configuredTtl()) ?? DEFAULT_CACHE_TTL;
  }

  /**
   * Vacía todas las cachés. Los repositorios ya creados conservan sus mapas, así que se vacían en sitio;
   * quien siga suscrito conserva el último valor y la siguiente consulta va al servidor.
   */
  clear(): void {
    this.caches.forEach((cache) => {
      [cache.listMap, cache.resourceMap, cache.resourceAclData].forEach((entries) => {
        Object.keys(entries).forEach((key) => delete entries[key]);
      });
    });
  }
}

function validTtl(value: unknown): number | undefined {
  const ms = Number(value);
  return value != null && Number.isFinite(ms) && ms >= 0 ? ms : undefined;
}
